contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(address spender, uint256 v0, uint256 v1) public {
        require(spender != address(0));
        require(v0 != 0);
        require(v1 != 0);
        bool okFirst = c.approve(spender, v0); if (__ESBMC_reverted()) return;
        uint256 beforeVal = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        bool okSecond = c.approve(spender, v1); if (__ESBMC_reverted()) return;
        uint256 afterVal = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        assert(okFirst && !okSecond && beforeVal == v0 && afterVal == beforeVal);
    }
}

