    function _run(address spender, uint256 v0, uint256 v1) internal {
        vm.assume(spender != address(0));
        vm.assume(v0 != 0);
        vm.assume(v1 != 0);
        bool okFirst;
        try c.approve(spender, v0) returns (bool __r) { okFirst = __r; } catch { return; }
        uint256 beforeVal;
        try c.allowance(address(this), spender) returns (uint256 __r) { beforeVal = __r; } catch { return; }
        bool okSecond;
        try c.approve(spender, v1) returns (bool __r) { okSecond = __r; } catch { return; }
